mapper.select:
SELECT C.CHALLENGE_NO, C.CHALLENGE_TITLE, C.CHALLENGE_DESC, C.CHALLENGE_TYPE, C.GOAL_COUNT, TO_CHAR(C.START_DATE, 'YYYY-MM-DD') AS START_DATE, TO_CHAR(C.END_DATE, 'YYYY-MM-DD') AS END_DATE, C.CHALLENGE_STATUS, M.MEMBER_NICKNAME, (SELECT COUNT(*) FROM CHALLENGE_MEMBER WHERE CHALLENGE_NO = C.CHALLENGE_NO) AS PARTICIPANT_COUNT FROM CHALLENGE C JOIN MEMBER M ON M.MEMBER_NO = C.MEMBER_NO WHERE 1=1
AND C.CHALLENGE_STATUS = #{status}
AND C.CHALLENGE_TYPE = #{type}
ORDER BY C.CHALLENGE_NO DESC

SELECT COUNT(*)
FROM CHALLENGE_MEMBER
WHERE CHALLENGE_NO = #{challengeNo}
AND MEMBER_NO = #{memberNo}

mapper.update:
UPDATE CHALLENGE_MEMBER
SET CERT_COUNT = CERT_COUNT + 1
WHERE CHALLENGE_NO = #{challengeNo}
AND MEMBER_NO = #{memberNo}

UPDATE CHALLENGE_MEMBER
SET IS_COMPLETE = 'Y'
WHERE CHALLENGE_NO = #{challengeNo}
AND MEMBER_NO = #{memberNo}
AND CERT_COUNT >= (
SELECT GOAL_COUNT FROM CHALLENGE
WHERE CHALLENGE_NO = #{challengeNo}
)

UPDATE CHALLENGE
SET CHALLENGE_STATUS = #{challengeStatus}
WHERE CHALLENGE_NO = #{challengeNo}
